def postageDrawerEvenKeyCensus(readings, k):
    a=readings
    out=[]
    m=max(a,default=0)
    dp=[m+1]*(m+1)
    dp[0]=0
    for x in range(1,m+1):
        for coin in (1,4,9):
            if coin<=x: dp[x]=min(dp[x],dp[x-coin]+1)
    out=[dp[x] for x in a]
    return sum(x%2==0 for x in out)

